<?php
require_once __DIR__ . '/includes/bootstrap.php';
$page = $_GET['page'] ?? 'dashboard';
if ($page === 'public') { require __DIR__ . '/public.php'; exit; }
if ($page === 'logout') { session_destroy(); header('Location: index.php'); exit; }
if (!is_admin()) {
  if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'setup') {
    $pw = $_POST['password'] ?? '';
    if (strlen($pw) < 8) $error = 'Password कम से कम 8 characters का होना चाहिए।';
    else { set_setting('admin_password_hash', password_hash($pw, PASSWORD_DEFAULT)); login_admin(); header('Location: index.php'); exit; }
  } elseif ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'login') {
    $hash = get_setting('admin_password_hash');
    if ($hash && password_verify($_POST['password'] ?? '', $hash)) { login_admin(); header('Location: index.php'); exit; }
    $error = 'गलत password।';
  }
  $setup = !get_setting('admin_password_hash');
  ?><!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NFC Business CP</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-bg"><form class="auth-card" method="post"><div class="brand-mark">N</div><h1>NFC Business CP</h1><p><?= $setup ? 'पहली बार इस्तेमाल: Admin password बनाएं।' : 'अपने dashboard में login करें।' ?></p><?php if (!empty($error)): ?><div class="alert"><?= h($error) ?></div><?php endif; ?><input type="hidden" name="action" value="<?= $setup ? 'setup' : 'login' ?>"><label>Admin password</label><input type="password" name="password" minlength="8" required placeholder="कम से कम 8 characters"><button class="btn primary full"><?= $setup ? 'Create password' : 'Login' ?></button><small>Password सुरक्षित hash के रूप में save होता है।</small></form></body></html><?php exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  csrf_check();
  $action = $_POST['action'] ?? '';
  if ($action === 'save') {
    $id = preg_replace('/[^0-9A-Za-z_-]/', '', trim($_POST['card_id'] ?? ''));
    $name = trim($_POST['name'] ?? '');
    if (!$id || !$name) { flash('Business ID और नाम जरूरी हैं।'); header('Location: index.php'); exit; }
    $data = [];
    foreach (['description','google_review','whatsapp','instagram','facebook','youtube','location'] as $k) $data[$k] = trim($_POST[$k] ?? '');
    $stmt = db()->prepare('INSERT INTO businesses(card_id,name,description,google_review,whatsapp,instagram,facebook,youtube,location,updated_at) VALUES(:id,:name,:description,:google_review,:whatsapp,:instagram,:facebook,:youtube,:location,CURRENT_TIMESTAMP) ON CONFLICT(card_id) DO UPDATE SET name=excluded.name,description=excluded.description,google_review=excluded.google_review,whatsapp=excluded.whatsapp,instagram=excluded.instagram,facebook=excluded.facebook,youtube=excluded.youtube,location=excluded.location,updated_at=CURRENT_TIMESTAMP');
    $stmt->execute(array_merge([':id'=>$id,':name'=>$name], array_combine(array_map(fn($x)=>':'.$x,array_keys($data)),array_values($data))));
    flash('Business save हो गया। Public link: '.public_url($id)); header('Location: index.php'); exit;
  }
  if ($action === 'delete') { $id = $_POST['card_id'] ?? ''; db()->prepare('DELETE FROM businesses WHERE card_id=?')->execute([$id]); flash('Business delete कर दिया गया।'); header('Location: index.php'); exit; }
}
$edit = null;
if (!empty($_GET['edit'])) { $s=db()->prepare('SELECT * FROM businesses WHERE card_id=?'); $s->execute([$_GET['edit']]); $edit=$s->fetch(); }
$rows = db()->query('SELECT * FROM businesses ORDER BY created_at DESC')->fetchAll();
$msg = take_flash();
?><!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · NFC Business CP</title><link rel="stylesheet" href="assets/style.css"><script src="https://unpkg.com/html5-qrcode"></script></head><body><div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">N</span><div><b>Modulos</b><small>NFC Business CP</small></div></div><nav><a class="active" href="index.php">▦ &nbsp; Dashboard</a><a href="#business-form">＋ &nbsp; Add Business</a></nav><a class="logout" href="index.php?page=logout">↪ Logout</a></aside><main class="main"><header class="topbar"><div><small>WORKSPACE / OVERVIEW</small><h1>Business Dashboard</h1></div><span class="status">● System ready</span></header><?php if($msg): ?><div class="notice"><?=h($msg)?></div><?php endif; ?><section class="stats"><div class="stat"><small>Total businesses</small><strong><?=count($rows)?></strong></div><div class="stat"><small>Public card pages</small><strong><?=count($rows)?></strong></div><div class="stat"><small>Hosting path</small><strong>/nfcbusinesscp/</strong></div></section><section class="panel" id="business-form"><div class="panel-head"><div><h2><?= $edit ? 'Edit Business' : 'Add Business' ?></h2><p>QR scan करके card का unique URL/ID capture करें या URL paste करें।</p></div></div><form method="post" class="form-grid" id="businessForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field full"><label>QR Code scan</label><div class="scan-row"><button type="button" class="btn secondary" onclick="startScanner()">Open camera scanner</button><input id="qrurl" placeholder="या QR का पूरा URL यहाँ paste करें"></div><div id="reader"></div><small>Camera permission दें। Scan URL से आखिरी ID अपने-आप Business ID में भर जाएगी।</small></div><div class="field"><label>Business / Card Unique ID *</label><input id="card_id" name="card_id" required value="<?=h($edit['card_id']??'')?> " placeholder="जैसे 20473"></div><div class="field"><label>Business name *</label><input name="name" required value="<?=h($edit['name']??'')?>" placeholder="Business name"></div><div class="field full"><label>Description</label><textarea name="description" rows="2"><?=h($edit['description']??'')?></textarea></div><?php foreach(['google_review'=>'Google Review URL','whatsapp'=>'WhatsApp number or link','instagram'=>'Instagram URL','facebook'=>'Facebook URL','youtube'=>'YouTube URL','location'=>'Location / Maps URL'] as $k=>$label): ?><div class="field"><label><?=h($label)?></label><input name="<?=h($k)?>" value="<?=h($edit[$k]??'')?>" placeholder="https://..."></div><?php endforeach; ?><div class="field full actions"><button class="btn primary">Save Business</button><a class="btn secondary" href="index.php">Clear form</a></div></form></section><section class="panel"><div class="panel-head"><div><h2>Your businesses</h2><p>Har ID ka public page alag URL par khulega.</p></div><input id="search" class="search" placeholder="Search business..."></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>Unique ID</th><th>Public page</th><th>Actions</th></tr></thead><tbody id="businessRows"><?php foreach($rows as $r): ?><tr><td><b><?=h($r['name'])?></b><small><?=h($r['description'])?></small></td><td><code><?=h($r['card_id'])?></code></td><td><a target="_blank" href="<?=h(public_url($r['card_id']))?>">Open page ↗</a></td><td class="row-actions"><a class="btn tiny secondary" href="index.php?edit=<?=urlencode($r['card_id'])?>">Edit</a><form method="post" onsubmit="return confirm('Delete this business?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="card_id" value="<?=h($r['card_id'])?>"><button class="btn tiny danger">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4" class="empty">अभी कोई business add नहीं है। ऊपर से पहला business add करें।</td></tr><?php endif; ?></tbody></table></div></section><footer>Modulos NFC Business CP · Starter build</footer></main></div><script src="assets/app.js"></script></body></html>
